<?php
declare(strict_types=1);

function blog_categories(bool $activeOnly=true): array {try{return db()->query("SELECT * FROM blog_categories".($activeOnly?" WHERE status=1":"")." ORDER BY sort_order,name")->fetchAll();}catch(Throwable $e){return [];}}
function blog_tags(): array {try{return db()->query("SELECT t.*,(SELECT COUNT(*) FROM blog_post_tags pt WHERE pt.tag_id=t.id) posts_count FROM blog_tags t ORDER BY t.name")->fetchAll();}catch(Throwable $e){return [];}}
function blog_slug(string $title,int $ignore=0): string {$base=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','-',$title),'-'));if($base==='')$base='blog-'.date('Ymd-His');$slug=$base;$n=2;while(true){$q=db()->prepare("SELECT id FROM blog_posts WHERE slug=?".($ignore?' AND id<>'.(int)$ignore:'')." LIMIT 1");$q->execute([$slug]);if(!$q->fetchColumn())return $slug;$slug=$base.'-'.$n++;}}
function blog_sync_scheduled(): void {if(!setting_bool('blog_scheduled_publishing',true))return;try{db()->exec("UPDATE blog_posts SET status='published' WHERE status='scheduled' AND published_at IS NOT NULL AND published_at<=NOW()");}catch(Throwable $e){}}
function blog_posts(array $filters=[],int $limit=12,int $offset=0): array {
    blog_sync_scheduled();$where=["p.status='published'","(p.published_at IS NULL OR p.published_at<=NOW())"];$params=[];
    if(!empty($filters['featured']))$where[]='p.is_featured=1';
    if(!empty($filters['post_type'])){$where[]='p.post_type=?';$params[]=(string)$filters['post_type'];}
    if(!empty($filters['language'])){$lang=(string)$filters['language'];if(in_array($lang,['en','ur'],true)){$where[]="(p.language=? OR p.language='bilingual')";$params[]=$lang;}}
    if(!empty($filters['category_id'])){$where[]='p.category_id=?';$params[]=(int)$filters['category_id'];}
    if(!empty($filters['category_slug'])){$where[]='c.slug=?';$params[]=(string)$filters['category_slug'];}
    if(!empty($filters['author_id'])){$where[]='p.author_id=?';$params[]=(int)$filters['author_id'];}
    if(!empty($filters['city_id'])){$where[]='p.city_id=?';$params[]=(int)$filters['city_id'];}
    elseif(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');
    if(!empty($filters['tag_slug'])){$where[]='EXISTS(SELECT 1 FROM blog_post_tags bpt JOIN blog_tags bt ON bt.id=bpt.tag_id WHERE bpt.post_id=p.id AND bt.slug=?)';$params[]=(string)$filters['tag_slug'];}
    if(!empty($filters['q'])){$q='%'.trim((string)$filters['q']).'%';$where[]='(p.title_en LIKE ? OR p.title_ur LIKE ? OR p.excerpt_en LIKE ? OR p.excerpt_ur LIKE ? OR u.name LIKE ?)';array_push($params,$q,$q,$q,$q,$q);}
    $sql="SELECT p.*,c.name category_name,c.slug category_slug,u.name author_name,ci.name city_name,b.name business_name,b.slug business_slug FROM blog_posts p LEFT JOIN blog_categories c ON c.id=p.category_id JOIN users u ON u.id=p.author_id LEFT JOIN cities ci ON ci.id=p.city_id LEFT JOIN businesses b ON b.id=p.business_id WHERE ".implode(' AND ',$where)." ORDER BY p.is_featured DESC,COALESCE(p.published_at,p.created_at) DESC,p.id DESC LIMIT ".max(1,min(100,$limit))." OFFSET ".max(0,$offset);
    try{$st=db()->prepare($sql);$st->execute($params);return $st->fetchAll();}catch(Throwable $e){return [];}
}
function blog_post(string $slug,bool $publishedOnly=true): ?array {$where=['p.slug=?'];$params=[$slug];if($publishedOnly){$where[]="p.status='published'";$where[]='(p.published_at IS NULL OR p.published_at<=NOW())';}if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'p.city_id');$sql="SELECT p.*,c.name category_name,c.slug category_slug,u.name author_name,ci.name city_name,b.name business_name,b.slug business_slug FROM blog_posts p LEFT JOIN blog_categories c ON c.id=p.category_id JOIN users u ON u.id=p.author_id LEFT JOIN cities ci ON ci.id=p.city_id LEFT JOIN businesses b ON b.id=p.business_id WHERE ".implode(' AND ',$where)." LIMIT 1";try{$q=db()->prepare($sql);$q->execute($params);return $q->fetch()?:null;}catch(Throwable $e){return null;}}
function blog_increment_view(int $id): void {try{db()->prepare("UPDATE blog_posts SET views=views+1 WHERE id=?")->execute([$id]);}catch(Throwable $e){}}
function blog_title(array $p,string $lang='en'): string {return $lang==='ur'?(trim((string)($p['title_ur']??''))?:trim((string)($p['title_en']??''))):(trim((string)($p['title_en']??''))?:trim((string)($p['title_ur']??'')));}
function blog_excerpt(array $p,string $lang='en'): string {return $lang==='ur'?(trim((string)($p['excerpt_ur']??''))?:trim((string)($p['excerpt_en']??''))):(trim((string)($p['excerpt_en']??''))?:trim((string)($p['excerpt_ur']??'')));}
function blog_body(array $p,string $lang='en'): string {return $lang==='ur'?(trim((string)($p['body_ur']??''))?:trim((string)($p['body_en']??''))):(trim((string)($p['body_en']??''))?:trim((string)($p['body_ur']??'')));}
function blog_post_tags(int $postId): array {try{$q=db()->prepare("SELECT t.* FROM blog_tags t JOIN blog_post_tags pt ON pt.tag_id=t.id WHERE pt.post_id=? ORDER BY t.name");$q->execute([$postId]);return $q->fetchAll();}catch(Throwable $e){return [];}}
function blog_set_tags(int $postId,array $tagIds): void {$tagIds=array_values(array_unique(array_filter(array_map('intval',$tagIds),fn($v)=>$v>0)));db()->prepare("DELETE FROM blog_post_tags WHERE post_id=?")->execute([$postId]);if(!$tagIds)return;$q=db()->prepare("INSERT IGNORE INTO blog_post_tags(post_id,tag_id) VALUES(?,?)");foreach($tagIds as $tagId)$q->execute([$postId,$tagId]);}
function blog_comments(int $postId,bool $approvedOnly=true): array {try{$q=db()->prepare("SELECT bc.*,u.name user_name FROM blog_comments bc LEFT JOIN users u ON u.id=bc.user_id WHERE bc.post_id=?".($approvedOnly?" AND bc.status='approved'":"")." ORDER BY bc.id ASC");$q->execute([$postId]);return $q->fetchAll();}catch(Throwable $e){return [];}}
function blog_add_comment(int $postId,string $name,string $email,string $text,?int $userId=null): void {if(!setting_bool('blog_comments_enabled',true))throw new RuntimeException('Comments are disabled.');$name=trim($name);$email=trim($email);$text=trim($text);if($name===''||mb_strlen($text)<2)throw new RuntimeException('Name and comment are required.');if(mb_strlen($name)>160||mb_strlen($text)>5000)throw new RuntimeException('Comment is too long.');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid email address.');$status=setting_bool('blog_comments_moderation',true)?'pending':'approved';$ip=(string)($_SERVER['REMOTE_ADDR']??'');$hash=$ip!==''?hash('sha256',$ip.'|'.(string)setting('site_name','ShahkotPK')):null;if($hash){try{$q=db()->prepare("SELECT created_at FROM blog_comments WHERE ip_hash=? ORDER BY id DESC LIMIT 1");$q->execute([$hash]);$last=$q->fetchColumn();if($last&&time()-strtotime((string)$last)<20)throw new RuntimeException('Please wait a few seconds before posting another comment.');}catch(RuntimeException $e){throw $e;}catch(Throwable $e){}}db()->prepare("INSERT INTO blog_comments(post_id,user_id,author_name,author_email,comment_text,status,ip_hash) VALUES(?,?,?,?,?,?,?)")->execute([$postId,$userId,$name,$email?:null,$text,$status,$hash]);}
function blog_widgets(bool $enabledOnly=true): array {try{return db()->query("SELECT w.*,c.name category_name,u.name author_name FROM blog_widgets w LEFT JOIN blog_categories c ON c.id=w.category_id LEFT JOIN users u ON u.id=w.author_id".($enabledOnly?' WHERE w.enabled=1':'')." ORDER BY w.sort_order,w.id")->fetchAll();}catch(Throwable $e){return [];}}
function blog_widget_posts(array $w): array {$f=[];if($w['widget_type']==='featured')$f['featured']=1;if($w['widget_type']==='category'&&!empty($w['category_id']))$f['category_id']=(int)$w['category_id'];if($w['widget_type']==='author'&&!empty($w['author_id']))$f['author_id']=(int)$w['author_id'];return blog_posts($f,max(1,min(12,(int)$w['item_limit'])));}
function blog_stats(?int $authorId=null): array {try{$where=[];$params=[];if($authorId){$where[]='author_id=?';$params[]=$authorId;}if(function_exists('tenant_apply_city_filter'))tenant_apply_city_filter($where,$params,'city_id');$sql="SELECT COUNT(*) total,SUM(status='published') published_count,SUM(status='draft') draft_count,SUM(status='scheduled') scheduled_count,SUM(is_featured=1) featured_count,COALESCE(SUM(views),0) total_views,COUNT(DISTINCT author_id) authors_count FROM blog_posts".($where?' WHERE '.implode(' AND ',$where):'');$q=db()->prepare($sql);$q->execute($params);$r=$q->fetch()?:[];$r['pending_comments']=$authorId?0:(int)db()->query("SELECT COUNT(*) FROM blog_comments WHERE status='pending'")->fetchColumn();return $r;}catch(Throwable $e){return ['total'=>0,'published_count'=>0,'draft_count'=>0,'scheduled_count'=>0,'featured_count'=>0,'total_views'=>0,'authors_count'=>0,'pending_comments'=>0];}}
function blog_author_candidates(): array {try{$rows=db()->query("SELECT u.id,u.name,u.role,u.status,COALESCE(up.approval_status,'approved') approval_status,up.custom_role_id,sr.permissions_json,sr.status custom_role_status FROM users u LEFT JOIN user_profiles up ON up.user_id=u.id LEFT JOIN system_roles sr ON sr.id=up.custom_role_id WHERE u.status='active' ORDER BY u.name LIMIT 1000")->fetchAll();$out=[];$core=core_role_registry();foreach($rows as $u){if($u['approval_status']!=='approved')continue;$allowed=false;if(($u['role']??'')==='admin'&&empty($u['custom_role_id']))$allowed=true;elseif(!empty($u['custom_role_id'])&&(int)($u['custom_role_status']??0)===1){$p=json_decode((string)($u['permissions_json']??'[]'),true);$allowed=is_array($p)&&in_array('blog.posts.create',$p,true);}else{$allowed=in_array('blog.posts.create',$core[$u['role']]['permissions']??[],true);}if($allowed)$out[]=['id'=>(int)$u['id'],'name'=>$u['name'],'role'=>$u['role']];}return $out;}catch(Throwable $e){return [];}}
function blog_author_posts_allowed(array $user): bool {return has_permission('blog.posts.edit_all',$user)||has_permission('blog.posts.edit_own',$user);}
function blog_can_edit_post(array $post,array $user): bool {return has_permission('blog.posts.edit_all',$user)||(has_permission('blog.posts.edit_own',$user)&&(int)$post['author_id']===(int)$user['id']);}
function blog_can_delete_post(array $post,array $user): bool {return has_permission('blog.posts.delete_all',$user)||(has_permission('blog.posts.delete_own',$user)&&(int)$post['author_id']===(int)$user['id']);}
function blog_video_embed_url(string $url): ?string {$url=trim($url);if($url==='')return null;if(preg_match('~(?:youtube\\.com/(?:watch\\?v=|embed/|shorts/)|youtu\\.be/)([A-Za-z0-9_-]{6,})~i',$url,$m))return 'https://www.youtube-nocookie.com/embed/'.$m[1];if(preg_match('~vimeo\\.com/(?:video/)?([0-9]+)~i',$url,$m))return 'https://player.vimeo.com/video/'.$m[1];return null;}
function blog_upgrade_homepage(): void {try{if(setting_int('blog_homepage_version',0)>=330)return;$page=cms_home_page();if(!$page)return;$sections=cms_page_sections($page);$found=false;foreach($sections as $s)if(($s['type']??'')==='blog_widgets'){$found=true;break;}if(!$found)$sections[]=['id'=>'blog_portal_widgets','type'=>'blog_widgets','enabled'=>1,'order'=>91,'title'=>'From the ShahkotPK Blog','subtitle'=>'Stories, guides & local perspectives','content'=>'Useful articles from local writers, editors and city experts.','image'=>'','items'=>''];usort($sections,fn($a,$b)=>(int)($a['order']??0)<=>(int)($b['order']??0));$order=10;foreach($sections as &$s){$s['order']=$order;$order+=10;}unset($s);$json=cms_encode_layout($sections);db()->prepare("UPDATE cms_pages SET layout_json=?,updated_at=NOW() WHERE id=?")->execute([$json,$page['id']]);if($page['is_home'])save_setting('homepage_sections',$json);save_setting('blog_homepage_version','330');}catch(Throwable $e){}}
